#' General Sample Size Simulation Framework
#'
#' A flexible function for simulating sample size requirements across different
#' data generation mechanisms, prediction models, and performance metrics.
#'
#' @param data_generation List specifying how to generate data:
#'   - method: "synthetic", "joint_mvn", "parametric", or "empirical"
#'   - params: method-specific parameters
#' @param predictor_config List with predictor specifications:
#'   - names: vector of predictor names
#'   - types: vector of types ("continuous", "binary", "categorical")
#'   - effects: named list of effect sizes (fixed or ranges)
#' @param reference_model Character: "lm", "glm", "ordinal", "lmm", or "glmm"
#' @param target_models Character vector: models to evaluate (e.g., c("lm", "rf", "gbm"))
#' @param sample_sizes Numeric vector or list(min, max, step)
#' @param n_simulations Integer: number of simulations per sample size
#' @param metrics Unique metric names: mse, rmse, mae, r_squared, auc, c_stat,
#'   accuracy, sensitivity, specificity, precision, recall, f1, or brier.
#' @param efficiency_threshold Numeric: target efficiency ratio (default 0.95)
#' @param cv_folds Number of CV folds; NULL uses a 70/30 split. Zero uses
#'   optimistic in-sample evaluation and is disallowed for ordered validation.
#' @param cv_repeats Integer: number of CV repetitions
#' @param model_options Named list of per-model tuning options, for example
#'   list(rf = list(ntree = 250), nnet = list(size = 4, decay = 0.001))
#' @param validation_strategy Character: "random" or "ordered". Ordered
#'   validation trains on earlier observations and evaluates later observations.
#' @param order_var Optional column name used to sort data for ordered validation.
#' @param lookup_table Optional reusable simulation table, prior simulation result,
#'   or path to a CSV table. Exact matches are reused without refitting.
#' @param seed Integer: random seed
#' @param parallel Logical; currently only FALSE is supported.
#' @param infinite_n Optional finite reference sample size, at least as large
#'   as every candidate size. NULL disables the additional reference run.
#' @param output_path Character: directory for saving results
#' @param verbose Logical: print progress messages
#' @return A sample_size_simulation object with nested results, minimum sample
#'   sizes, configuration, finite reference results, a reusable simulation_table,
#'   cache statistics, and summary_plots. The q025 and q975 columns are empirical
#'   simulation quantiles, not confidence limits for the mean.
#' @details For error metrics, efficiency is (error at smallest n - error at
#'   current n) / (error at smallest n - error at largest n). For higher-is-better
#'   metrics it is current performance / performance at largest n. Ratios are
#'   clipped to [0, 1]. A worsening error reference or nonpositive higher-is-better
#'   reference yields missing efficiency. Equal endpoint errors are assigned
#'   efficiency one by convention. This descriptive rule is not a power analysis
#'   or a sequential statistical stopping test. The argument infinite_n denotes
#'   a finite additional simulation, not a known asymptote.
#'
#'   Sample sizes refer to total generated rows; CV training sets are smaller.
#'   Empirical generation bootstraps rows from a plug-in population, so duplicate
#'   original records can occur across random folds. It does not establish
#'   performance on independent real observations. Ordered validation is therefore
#'   disallowed with empirical or synthetic resampling. For actual time series,
#'   evaluate the original observations with fit_and_evaluate_model(). That
#'   evaluator does not implement purging, a temporal gap, or grouped folds.
#'
#'   Generated mixed-model data include a .group column; mixed targets use random
#'   intercepts and population-level predictions. Parametric categorical
#'   predictors must use numeric scores. Use empirical data for factor predictors.
#' @examples
#' result <- run_general_simulation(
#'   sample_sizes = c(30, 60), n_simulations = 2,
#'   target_models = "lm", metrics = "mse", infinite_n = NULL,
#'   cv_folds = 3, cv_repeats = 1, verbose = FALSE
#' )
#' summary(result)
#' cached <- run_general_simulation(
#'   sample_sizes = c(30, 60), n_simulations = 2,
#'   target_models = "lm", metrics = "mse", infinite_n = NULL,
#'   cv_folds = 3, cv_repeats = 1, verbose = FALSE, lookup_table = result
#' )
#' cached$cache$fraction_reused

#' @export
run_general_simulation <- function(
  data_generation = list(
    method = "joint_mvn",
    params = list(
      correlation_matrix = diag(3),
      covariance_matrix = NULL,
      mean_vector = NULL
    )
  ),
  predictor_config = list(
    names = c("x1", "x2", "x3"),
    types = c("continuous", "continuous", "continuous"),
    effects = list(
      fixed = c(0.5, -0.3, 0.2),
      ranges = NULL  # alternatively: list(x1 = c(0.3, 0.7), ...)
    )
  ),
  reference_model = "lm",
  target_models = c("lm", "glm"),
  sample_sizes = list(min = 50, max = 500, step = 25),
  n_simulations = 1000,
  metrics = c("mse", "r_squared"),
  efficiency_threshold = 0.95,
  infinite_n = 10000,
  cv_folds = 5,
  cv_repeats = 2,
  model_options = list(),
  validation_strategy = c("random", "ordered"),
  order_var = NULL,
  lookup_table = NULL,
  seed = 2025,
  parallel = FALSE,
  output_path = NULL,
  verbose = TRUE
) {
  validation_results <- NULL
  validation_strategy <- match.arg(validation_strategy)
  validate_simulation_inputs(
    data_generation, predictor_config, target_models, n_simulations, metrics,
    efficiency_threshold, infinite_n, cv_folds, cv_repeats, seed, parallel,
    verbose, validation_strategy
  )
  if (!is.null(seed)) {
    had_seed <- exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)
    if (had_seed) old_seed <- get(".Random.seed", envir = .GlobalEnv)
    on.exit({
      if (had_seed) assign(".Random.seed", old_seed, envir = .GlobalEnv)
      else if (exists(".Random.seed", envir = .GlobalEnv, inherits = FALSE)) {
        rm(".Random.seed", envir = .GlobalEnv)
      }
    }, add = TRUE)
  }

  # ---- Canonicalize model names ----
  reference_model <- normalize_model_type(reference_model)
  target_models <- vapply(target_models, normalize_model_type, character(1))
  target_models <- unique(target_models)

  model_registry <- get_model_registry()
  valid_reference_models <- model_registry$model[model_registry$reference_model]
  if (!reference_model %in% valid_reference_models) {
    stop(
      "reference_model must be one of: ",
      paste(valid_reference_models, collapse = ", "),
      ". Received: ",
      reference_model
    )
  }

  valid_target_models <- model_registry$model
  invalid_target_models <- setdiff(target_models, valid_target_models)
  if (length(invalid_target_models) > 0) {
    stop(
      "Unsupported target_models: ",
      paste(invalid_target_models, collapse = ", "),
      ". Supported target models are: ",
      paste(valid_target_models, collapse = ", ")
    )
  }

  if (is.null(model_options)) model_options <- list()
  if (!is.list(model_options)) stop("model_options must be a named list by model")
  if (length(model_options) > 0) {
    if (is.null(names(model_options)) || any(!nzchar(names(model_options)))) {
      stop("model_options must be a named list by model")
    }
    normalized_option_names <- vapply(
      names(model_options), normalize_model_type, character(1)
    )
    if (anyDuplicated(normalized_option_names)) {
      stop("model_options contains duplicate model names after alias normalization")
    }
    names(model_options) <- normalized_option_names
    unknown_option_models <- setdiff(names(model_options), target_models)
    if (length(unknown_option_models) > 0) {
      stop(
        "model_options supplied for models not in target_models: ",
        paste(unknown_option_models, collapse = ", ")
      )
    }
  }
  for (model in target_models) {
    model_options[[model]] <- resolve_model_options(
      model, model_options[[model]] %||% list()
    )
  }

  if (!is.null(order_var) &&
      (!is.character(order_var) || length(order_var) != 1 || is.na(order_var))) {
    stop("order_var must be NULL or a single non-missing column name")
  }
  if (validation_strategy != "ordered" && !is.null(order_var)) {
    warning("order_var is ignored unless validation_strategy = 'ordered'")
  }

  # ---- Process sample sizes ----
  sample_sizes <- process_sample_sizes(sample_sizes)
  if (!is.null(cv_folds) && cv_folds >= min(sample_sizes)) {
    stop("cv_folds must be smaller than every sample size")
  }
  if (!is.null(infinite_n) && infinite_n < max(sample_sizes)) {
    stop("infinite_n must be at least as large as every sample size")
  }
  if (validation_strategy == "ordered" &&
      data_generation$method %in% c("empirical", "synthetic")) {
    stop("Ordered validation cannot use row-bootstrap or synthetic resampling; ",
         "use fit_and_evaluate_model() on the original ordered data")
  }

  # Append infinite_n to sample sizes if specified.
  if (!is.null(infinite_n) && infinite_n > 0) {
    if (verbose) message("Adding infinite sample size (n = ", infinite_n, ") for asymptotic reference")
    sample_sizes <- c(sample_sizes[sample_sizes != infinite_n], infinite_n)
  }

  simulation_keys <- create_simulation_keys(
    target_models = target_models,
    model_options = model_options,
    data_generation = data_generation,
    predictor_config = predictor_config,
    reference_model = reference_model,
    n_simulations = n_simulations,
    cv_folds = cv_folds,
    cv_repeats = cv_repeats,
    seed = seed,
    validation_strategy = validation_strategy,
    order_var = order_var
  )
  lookup_table <- load_simulation_table(lookup_table)

  # ---- Load required packages ----
  required_pkgs <- "MASS"

  for (pkg in required_pkgs) {
    if (!requireNamespace(pkg, quietly = TRUE)) {
      stop(paste("Package", pkg, "is required but not installed."))
    }
  }

  # Validate model-specific package dependencies up front.
  models_requiring_fit <- target_models
  if (!is.null(lookup_table)) {
    models_requiring_fit <- unique(unlist(lapply(sample_sizes, function(n) {
      target_models[vapply(target_models, function(model) {
        rows <- lookup_table[
          lookup_table$simulation_key %in% simulation_keys[[model]] &
            lookup_table$model == model &
            lookup_table$sample_size == n,
          , drop = FALSE
        ]
        !all(metrics %in% rows$metric)
      }, logical(1))]
    }), use.names = FALSE))
  }

  required_model_pkgs <- unique(
    model_registry$package[match(models_requiring_fit, model_registry$model)]
  )
  required_model_pkgs <- setdiff(required_model_pkgs, c("stats", required_pkgs))

  for (pkg in required_model_pkgs) {
    if (!requireNamespace(pkg, quietly = TRUE)) {
      stop(paste("Package", pkg, "is required for selected target models but is not installed."))
    }
  }

  n_sample_sizes <- length(sample_sizes)

  # ---- Set seed ----
  if (!is.null(seed)) set.seed(seed)

  # ---- Initialize storage structures ----
  results <- initialize_results_storage(
    sample_sizes = sample_sizes,
    target_models = target_models,
    metrics = metrics,
    predictor_config = predictor_config
  )

  # ---- Main simulation loop ----
  if (verbose) message("Starting simulation across ", n_sample_sizes, " sample sizes...")
  cache_hits <- 0L
  total_model_sample_combinations <- length(target_models) * n_sample_sizes

  for (i_size in seq_along(sample_sizes)) {
    n <- sample_sizes[i_size]
    if (verbose) message("\n=== Sample size: ", n, " (", i_size, "/", n_sample_sizes, ") ===")

    restored <- restore_results_from_table(
      results = results,
      lookup_table = lookup_table,
      simulation_keys = simulation_keys,
      target_models = target_models,
      metrics = metrics,
      n = n,
      i_size = i_size
    )
    results <- restored$results
    cached_models <- restored$cached_models
    models_to_run <- setdiff(target_models, cached_models)
    cache_hits <- cache_hits + length(cached_models)

    if (verbose && length(cached_models) > 0) {
      message("  Reused table rows for: ", paste(cached_models, collapse = ", "))
    }
    if (length(models_to_run) == 0) next

    # Storage for this sample size
    sim_results_n <- initialize_sim_storage(n_simulations, models_to_run, metrics)

    # Run simulations
    for (sim in seq_len(n_simulations)) {
      if (verbose && sim %% 100 == 0) message("  Simulation ", sim, "/", n_simulations)

      # 1. Generate data based on specified method
      sim_data <- generate_data(
        n = n,
        data_generation = data_generation,
        predictor_config = predictor_config,
        reference_model = reference_model,
        seed = derive_simulation_seed(seed, n, sim, "data")
      )

      # 2. Fit and evaluate each target model
      for (model_name in models_to_run) {
        # Reset a common evaluation stream so competing models use identical
        # random splits while remaining independent of target-model order.
        model_seed <- derive_simulation_seed(seed, n, sim, "evaluation")
        if (!is.null(model_seed)) set.seed(model_seed)
        model_metrics <- fit_and_evaluate_model(
          data = sim_data,
          model_type = model_name,
          response_var = "y",
          predictor_vars = predictor_config$names,
          metrics = metrics,
          cv_folds = cv_folds,
          cv_repeats = cv_repeats,
          model_options = model_options[[model_name]],
          validation_strategy = validation_strategy,
          order_var = order_var
        )

        # Store results
        for (metric_name in metrics) {
          sim_results_n[[model_name]][[metric_name]][sim] <- model_metrics[[metric_name]]
        }
      }
    }

    # Aggregate results for this sample size
    results <- aggregate_results(results, sim_results_n, n, i_size)
  }

  # ---- Post-processing ----
  # Extract infinite sample results for efficiency calculation
  infinite_results <- NULL
  if (!is.null(infinite_n) && infinite_n > 0) {
    infinite_results <- list(
      n = infinite_n,
      metrics = lapply(results, function(model_results) {
        lapply(model_results, function(metric_df) {
          metric_df[metric_df$sample_size == infinite_n, , drop = FALSE]
        })
      })
    )
    if (verbose) message("\nInfinite sample (n = ", infinite_n, ") metrics extracted as reference")
  }

  # Calculate efficiency metrics using infinite sample as reference
  results <- calculate_efficiency_metrics(results, efficiency_threshold)

  # Determine minimum sample sizes
  min_sample_sizes <- determine_minimum_sample_sizes(
    results,
    efficiency_threshold,
    metrics
  )

  simulation_table <- results_to_simulation_table(results, simulation_keys)

  # ---- Save results ----
  if (!is.null(output_path)) {
    save_simulation_results(
      results = results,
      min_sample_sizes = min_sample_sizes,
      validation_results = validation_results,
      output_path = output_path,
      timestamp = format(Sys.time(), "%Y%m%d_%H%M%S"),
      simulation_table = simulation_table
    )
  }

  # ---- Return comprehensive results object ----
  output <- list(
    results = results,
    infinite_results = infinite_results,
    min_sample_sizes = min_sample_sizes,
    configuration = list(
      data_generation = data_generation,
      predictor_config = predictor_config,
      reference_model = reference_model,
      target_models = target_models,
      sample_sizes = sample_sizes,
      n_simulations = n_simulations,
      metrics = metrics,
      efficiency_threshold = efficiency_threshold,
      infinite_n = infinite_n,
      cv_folds = cv_folds,
      cv_repeats = cv_repeats,
      model_options = model_options,
      validation_strategy = validation_strategy,
      order_var = order_var,
      seed = seed
    ),
    simulation_table = simulation_table,
    cache = list(
      reused_model_sample_combinations = cache_hits,
      total_model_sample_combinations = total_model_sample_combinations,
      fraction_reused = if (total_model_sample_combinations == 0) 0 else
        cache_hits / total_model_sample_combinations
    ),
    summary_plots = generate_summary_plots(results, min_sample_sizes)
  )

  class(output) <- "sample_size_simulation"
  return(output)
}
